ph = None
t0 = 0.0

def control(obs):
    global ph, t0
    t = obs.get('t', 0.0)
    st = obs.get('status')
    h = obs.get('hitch_deg', 0.0)
    mot = obs.get('motion', {}) or {}
    if mot.get('hold_s', 0.0) and mot.get('hold_s', 0.0) > 0:
        return (0.0, 0.0)
    rear = obs.get('rig', {}).get('trailer_rear', [-6.3, 0.0])
    y = rear[1]
    if st in ('PINNED', 'JACKKNIFED') and ph != 'fwd':
        ph = 'fwd'
        t0 = None
    if ph is None:
        ph = 'fwd'
    if ph == 'fwd':
        if t0 is None:
            t0 = t
        if t - t0 < 2.5:
            return (25.0, 0.8)
        ph = 'rev'
        t0 = t
    desired = max(-8.0, min(8.0, -1.5 * y))
    steer = 3.0 * (h - desired)
    steer = max(-35.0, min(35.0, steer))
    return (steer, -0.8)

