ph = 'fwd'
dist = 0.0

def control(obs):
    global ph, dist
    st = obs.get('status')
    mot = obs.get('motion', {}) or {}
    if (mot.get('hold_s', 0.0) or 0.0) > 0:
        return (0.0, 0.0)
    dt = obs.get('dt', 0.1) or 0.1
    v = mot.get('v_mps', 0.0) or 0.0
    h = obs.get('hitch_deg', 0.0) or 0.0
    rear = obs.get('rig', {}).get('trailer_rear', [-6.3, 0.0])
    y = rear[1]
    if st in ('PINNED', 'JACKKNIFED') and ph == 'rev':
        ph = 'fwd'
        dist = 0.0
    if ph == 'fwd':
        if v > 0.05:
            dist += v * dt
        if dist < 3.0:
            return (12.0, 0.8)
        ph = 'rev'
        return (0.0, 0.0)
    desired = max(-8.0, min(8.0, -1.2 * y))
    steer = 2.5 * (h - desired)
    steer = max(-30.0, min(30.0, steer))
    return (steer, -0.6)

