    st = obs.get('status', 'READY')
    h = obs.get('hitch_deg', 0.0)
    v = (obs.get('motion') or {}).get('v_mps', 0.0)
    rig = obs.get('rig') or {}
    rr = rig.get('trailer_rear', [0.0, 0.0])
    ry = rr[1] if len(rr) > 1 else 0.0
    if S['t0'] is None:
        S['t0'] = t
    if st in ('JACKKNIFED', 'PINNED') and S['m'] == 'rev':
        S['m'] = 'fwd'
        S['t0'] = t
    if S['m'] == 'fwd':
        if (ry < -3.2 and v >= 0.0) or (t - S['t0'] > 12.0):
            S['m'] = 'rev'
            S['t0'] = t
        else:
            return (-25.0, 0.5, -41.0)
    target = -4.0 - 2.0 * (ry + 3.0)
    if target > 2.0:
        target = 2.0
    if target < -10.0:
        target = -10.0
    s = 2.5 * (h - target)
    if s > 30.0:
        s = 30.0
    if s < -30.0:
        s = -30.0
    return (s, -0.3, -41.0)

